        }
}

pub fn expand(allocator: Allocator, tokens: []Token, out: []std.array_list.Managed(u8), contains_nested: bool) ExpandError!void {
        var out_key_counter: u16 = 1;
        _ = &out_key_counter;
        if ((!contains_nested)) {
            var expansions_table = try buildExpansionTableAlloc(allocator, tokens);
            _ = &expansions_table;
            return try expandFlat(tokens, expansions_table.items[0..], out, 0, (&out_key_counter), 0, 0, tokens.len);
        }
        var parser = Parser.init(tokens, allocator);
        _ = &parser;
        var root_node = try parser.parse();
        _ = &root_node;
        _ = try expandNested(root_node, out, 0, (&out_key_counter), 0);
}

pub fn calculateExpandedAmount(tokens: []const Token) u32 {
        const StackEntry = struct {
    segment_product: u32 = 1,
    accumulator: u32 = 0,
};
        const NestedBraceStack = bun.SmallList(StackEntry, MAX_NESTED_BRACES);
        var nested_brace_stack = NestedBraceStack{  };
        _ = &nested_brace_stack;
        defer {
        _ = nested_brace_stack.deinit(bun.default_allocator);
        }
        var variant_count: u32 = 0;
        _ = &variant_count;
        for (cp_iter_slice(tokens)) |tok| {
            _ = &tok;
            switch (tok) {
.open => {
_ = nested_brace_stack.append(bun.default_allocator, .{});
},
.comma => {
var top = (nested_brace_stack.lastMut()).?;
            _ = &top;
            top.accumulator = (top.accumulator +| top.segment_product);
            top.segment_product = 1;
},
.close => {
const entry = (nested_brace_stack.pop()).?;
            const total = (entry.accumulator +| entry.segment_product);
            if ((nested_brace_stack.len() > 0)) {
                var parent = (nested_brace_stack.lastMut()).?;
                _ = &parent;
                parent.segment_product = (blk_catch_0: { break :blk_catch_0 ((std.math.mul(u32, parent.segment_product, total)) catch |__ce_0| { _ = &__ce_0; break :blk_catch_0 std.math.maxInt(u32); }); });
            } else {
                if ((variant_count == 0)) {
                    variant_count = total;
                } else {
                    variant_count = (blk_catch_1: { break :blk_catch_1 ((std.math.mul(u32, variant_count, total)) catch |__ce_1| { _ = &__ce_1; break :blk_catch_1 std.math.maxInt(u32); }); });
                }
            }
},
else => {

},
}
        }
        return variant_count;
}

pub fn NewLexer(comptime encoding: Encoding) type {
        const Chars = NewChars(encoding);
        return struct {
    chars: Chars,
    alloc: Allocator,
    tokens: ArrayList(Token),
    contains_nested: bool = false,

pub fn tokenize(alloc: Allocator, src: []const u8) BraceLexerError!Output {
            var this = Self{ .chars = Chars.init(src), .tokens = ArrayList(Token).init(alloc), .alloc = alloc };
            _ = &this;
            const contains_nested = try this.tokenize_impl();
            return Output{ .tokens = this.tokens, .contains_nested = contains_nested };
    }

pub fn tokenize_impl(self: *@This()) BraceLexerError!bool {
            const BraceStack = bun.SmallList(u32, MAX_NESTED_BRACES);
            var brace_stack = BraceStack{  };
            _ = &brace_stack;
            defer {
            _ = brace_stack.deinit(bun.default_allocator);
            }
            while (true) {
                var input_opt = self.eat();
                _ = &input_opt;
                if ((input_opt == null)) {
                    break;
                }
                const input = input_opt.?;
                const char = input.char;
                const escaped = input.escaped;
                if ((!escaped)) {
                    switch (char) {
'{' => {
_ = brace_stack.append(bun.default_allocator, @intCast(self.tokens.items.len));
                    _ = try self.tokens.append(.{ .open = .{} });
                    continue;
},
'}' => {
if ((brace_stack.len() > 0)) {
                        _ = brace_stack.pop();
                        _ = try self.tokens.append(.close);
                        continue;
                    }
},
',' => {
if ((brace_stack.len() > 0)) {
                        _ = try self.tokens.append(.comma);
                        continue;
                    }
},
else => {

},
}
                }
                _ = try self.appendChar(char);
            }
            while ((brace_stack.len() > 0)) {
                const top_idx = (brace_stack.pop()).?;
                _ = self.rollbackBraces(top_idx);
            }
            _ = try self.flattenTokens();
            _ = try self.tokens.append(.eof);
            return self.contains_nested;
    }

pub fn flattenTokens(self: *@This()) Allocator.Error!void {
            if ((self.tokens.items.len == 0)) {
                return;
            }
            var brace_count: u32 = (if ((self.tokens.items[0] == .open)) 1 else 0);
            _ = &brace_count;
            var i: u32 = 0;
            _ = &i;
            var j: u32 = 1;
            _ = &j;
            while (((i < self.tokens.items.len) and (j < self.tokens.items.len))) {
                var itok = (&self.tokens.items[@as(usize, @intCast(i))]);
                _ = &itok;
                var jtok = (&self.tokens.items[@as(usize, @intCast(j))]);
                _ = &jtok;
                if (((itok.* == .text) and (jtok.* == .text))) {
                    _ = try itok.text.appendSlice(self.alloc, jtok.toText().slice());
                    _ = self.tokens.orderedRemove(j);
                } else {
                    if ((jtok.* == .close)) {
                        brace_count = (brace_count - 1);
                    } else {
                        if ((jtok.* == .open)) {
                            brace_count = (brace_count + 1);
                            if ((brace_count > 1)) {
                                self.contains_nested = true;
                            }
                        }
                    }
                    i = (i + 1);
                    j = (j + 1);
                }
            }
    }

pub fn rollbackBraces(self: *@This(), starting_idx: u32) void {
            if (bun.Environment.allow_assert) {
                const first = (&self.tokens.items[@as(usize, @intCast(starting_idx))]);
                _ = assert((first.* == .open));
            }
            var braces: u8 = 0;
            _ = &braces;
            _ = self.replaceTokenWithString(starting_idx);
            var i: u32 = (starting_idx + 1);
            _ = &i;
            while ((i < self.tokens.items.len)) : (i = (i + 1)) {
                if ((braces > 0)) {
                    switch (self.tokens.items[@as(usize, @intCast(i))]) {
.open => {
braces = (braces + 1);
},
.close => {
braces = (braces - 1);
},
else => {

},
}
                    continue;
                }
                switch (self.tokens.items[@as(usize, @intCast(i))]) {
.open => {
braces = (braces + 1);
                continue;
},
.close, .comma, .text => {
_ = self.replaceTokenWithString(i);
},
.eof => {

},
}
            }
    }

pub fn replaceTokenWithString(self: *@This(), token_idx: u32) void {
            var tok = (&self.tokens.items[@as(usize, @intCast(token_idx))]);
            _ = &tok;
            const tok_text = tok.toText();
            tok.* = .{ .text = tok_text };
    }

pub fn appendChar(self: *@This(), char: Chars.CodepointType) Allocator.Error!void {
            if ((self.tokens.items.len > 0)) {
                var last = (&self.tokens.items[@as(usize, @intCast((self.tokens.items.len - 1)))]);
                _ = &last;
                if ((last.* == .text)) {
                    if (comptime (encoding == .ascii)) {
                        _ = try last.text.appendChar(self.alloc, char);
                        return;
                    }
                    var buf: [4]u8 = .{ 0, 0, 0, 0 };
                    _ = &buf;
                    const len = bun.strings.encodeWTF8Rune((&buf), @bitCast(char));
                    _ = try last.text.appendSlice(self.alloc, buf[0..len]);
                    return;
                }
            }
            if (comptime (encoding == .ascii)) {
                const char_arr: [1]u8 = .{ char };
                _ = try self.tokens.append(.{ .text = try SmolStr.fromSlice(self.alloc, (&char_arr)) });
            } else {
                var buf: [4]u8 = .{ 0, 0, 0, 0 };
                _ = &buf;
                const len = bun.strings.encodeWTF8Rune((&buf), @bitCast(char));
                _ = try self.tokens.append(.{ .text = try SmolStr.fromSlice(self.alloc, buf[0..len]) });
            }
    }

pub fn eat(self: *@This()) ?Chars.InputChar {
            return self.chars.eat();
    }

pub fn read_char(self: *@This()) ?Chars.InputChar {
            return self.chars.read_char();
    }
    pub const Output = struct {
                tokens: ArrayList(Token),
                contains_nested: bool,
            };
    const Self = @This();
};
}
